#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""
SELF-HEAL-001 Self-Healing System
Automatically detects and fixes issues without human intervention
"""
import json, re, sys, time
from pathlib import Path
from datetime import datetime
from collections import defaultdict

TOOLS_DIR = Path("30-scripts-tools")
HEAL_LOG = Path("13-memory/.self_heal_log.json")

HEAL_RULES = {
    "bare_except": {
        "pattern": r'except\s*:\s*$',
        "fix": "(IOError, OSError)",
        "severity": "high"
    },
    "missing_encoding": {
        "pattern": r'open\([^)]+\)\s*(?!.*encoding=)',
        "fix": 'open(f"path", "r", encoding="utf-8")',
        "severity": "medium"
    },
    "hardcoded_timeout": {
        "pattern": r'timeout\s*=\s*30(?!0)',
        "fix": "timeout=300",
        "severity": "low"
    }
}

class SelfHealSystem:
    def __init__(self):
        self.fixes = []
        self.health_score = 100

    def diagnose_file(self, filepath):
        """Diagnose issues in a single file"""
        try:
            content = filepath.read_text(encoding="utf-8", errors="replace")
        except:
            return []

        issues = []
        lines = content.split("\n")

        for i, line in enumerate(lines):
            for issue_type, rule in HEAL_RULES.items():
                if re.search(rule["pattern"], line):
                    issues.append({
                        "file": filepath.name,
                        "line": i + 1,
                        "type": issue_type,
                        "severity": rule["severity"],
                        "content": line.strip()
                    })

        return issues

    def heal_file(self, filepath, issues):
        """Auto-heal a file"""
        try:
            content = filepath.read_text(encoding="utf-8", errors="replace")
        except:
            return False

        original = content

        for issue in issues:
            if issue["type"] == "bare_except":
                # Check context
                lines = content.split("\n")
                line_idx = issue["line"] - 1
                if 0 <= line_idx < len(lines):
                    line = lines[line_idx]
                    if re.match(r'^\s+except\s*:\s*$', line):
                        # Detect context
                        indent = len(line) - len(line.lstrip())
                        spaces = " " * indent

                        # Look back for context
                        context = ""
                        for j in range(max(0, line_idx-5), line_idx):
                            prev_line = lines[j]
                            if "json.load" in prev_line or "json.loads" in prev_line:
                                context = "(json.JSONDecodeError, IOError, OSError)"
                                break
                            elif "open(" in prev_line:
                                context = "(IOError, OSError, UnicodeDecodeError)"
                                break
                            elif "subprocess" in prev_line:
                                context = "(subprocess.SubprocessError, OSError)"
                                break

                        if not context:
                            context = "(Exception,)"

                        new_line = f"{spaces}except {context}:"
                        lines[line_idx] = new_line
                        content = "\n".join(lines)

        if content != original:
            filepath.write_text(content, encoding="utf-8")
            return True
        return False

    def run_diagnosis(self):
        """Run full system diagnosis"""
        all_issues = []

        for f in TOOLS_DIR.glob("*_001.py"):
            issues = self.diagnose_file(f)
            all_issues.extend(issues)

        # Categorize by severity
        by_severity = defaultdict(list)
        for issue in all_issues:
            by_severity[issue["severity"]].append(issue)

        return {
            "total": len(all_issues),
            "high": len(by_severity["high"]),
            "medium": len(by_severity["medium"]),
            "low": len(by_severity["low"]),
            "issues": all_issues
        }

    def auto_heal(self, dry_run=False):
        """Auto-heal all detected issues"""
        diagnosis = self.run_diagnosis()
        healed = []

        if dry_run:
            return {"mode": "dry-run", "would_heal": diagnosis["total"], "issues": diagnosis["issues"]}

        # Group by file
        by_file = defaultdict(list)
        for issue in diagnosis["issues"]:
            by_file[issue["file"]].append(issue)

        for filename, issues in by_file.items():
            filepath = TOOLS_DIR / filename
            if self.heal_file(filepath, issues):
                healed.append({"file": filename, "count": len(issues)})

        # Calculate new health
        new_diagnosis = self.run_diagnosis()
        self.health_score = max(0, 100 - new_diagnosis["total"] * 2)

        return {
            "healed": healed,
            "remaining": new_diagnosis["total"],
            "health_score": self.health_score
