    "brainstorm": ["brainstorm", "idea", "think", "头脑风暴", "创意"],
    "operate": ["operate", "manage", "monitor", "运营", "管理"],
}

class IntentPredictor:
    def __init__(self):
        self.history = self.load_history()

    def load_history(self):
