            "total_interactions": len(intents),
            "top_intents": intent_counts.most_common(5),
            "last_intent": last_intent,
            "predicted_next": predicted,
            "confidence": confidence,
            "learned_patterns": len(self.learn_log.get("entries", []))
        }


